require("Game.Views.ItemViews.FishEyeScrollViewItem")
FishEyeScrollViewCommon = class("FishEyeScrollViewCommon")
function FishEyeScrollViewCommon:ctor()
end

--传递进来的pGameObject为作为面板使用的GameObject的根节点
function FishEyeScrollViewCommon:InitPanel(pGameObject)
    self.gameObject = pGameObject;
    self.transform = pGameObject.transform;
    self:FindComponent(self.transform);
    self.usedItemList = {};
    self.recycledItemList = {};
    self.itemCallback = nil;
    self.data = nil;
    if (self.scrollView.onDragFinished) then
        self.scrollView.onDragFinished = self.scrollView.onDragFinished + function () self:OnDragFinished(); end
    else
        self.scrollView.onDragFinished = function () self:OnDragFinished(); end
    end
end

function FishEyeScrollViewCommon:OnDragFinished()
    coroutine.start(function()
        coroutine.wait(0.5)
        if self.centerOnChild.centeredObject then
            local tempTrigger = self.centerOnChild.centeredObject:GetComponent("UIEventTrigger");
            EventDelegate.Execute(tempTrigger.onClick);
        end
    end)
end

function FishEyeScrollViewCommon:FindComponent(transform)
    local tTransform = transform;
    self.scrollView = Util.FindChildEx(tTransform,"ScrollView"):GetComponent("UIScrollView");
    self.wrapContent = Util.FindChildEx(tTransform,"ScrollView/WrapContent"):GetComponent("UIWrapContent");
    self.grid = Util.FindChildEx(tTransform,"ScrollView/Grid"):GetComponent("UIGrid");
    self.centerOnChild = Util.FindChildEx(tTransform,"ScrollView/Grid"):GetComponent("UICenterOnChild");
    self.recovery = Util.FindChildEx(tTransform,"recovery");
    self.obj_item = Util.FindChildEx(tTransform,"recovery/Hero").gameObject;
end

function FishEyeScrollViewCommon:Init(data, itemId, itemCallback)
    if data == nil or #data == 0 then
        print("此处 data 不应为 nil 或 空表")
        return;
    end
    self.data = data;
    self.itemId = itemId;
    self.itemCallback = itemCallback;
    self:SetItemList();
end

function FishEyeScrollViewCommon:ItemOnClick(item)
    self.centerOnChild:CenterOn(item.transform)
    if self.itemCallback then
        self.itemCallback(item.heroId);
    end
end

function FishEyeScrollViewCommon:SetItemList()
    PrefabTool.AdjustPrefabItemCount(#self.data, self.recovery, self.grid.transform,
            self.usedItemList, self.recycledItemList, self.obj_item, FishEyeScrollViewItem);
    for i = 1, #self.usedItemList do
        self.usedItemList[i]:SetItem(self.data[i], function(item) self:ItemOnClick(item) end);
    end
    self.grid:Reposition();
    self.scrollView:ResetPosition();
    coroutine.start(function()
        coroutine.wait(0.1)
        if self.itemId then
            local tran = self.grid:GetChild(self.itemId - 1);
            self.centerOnChild:CenterOn(tran);
        end
    end)
end